@startuml

class RepairShop {
  + name
  + address
  + numberOfEmployees
}

class Employee {
  + taxCode
  + address
  + phoneNumber
  + yearsOfService
}

class Director extends Employee {
  + age
}

class Repair {
  + code
  + checkInTime
  + checkInDate
  + returnTime
  + returnDate
}

class Vehicle {
  + model
  + type
  + licensePlate
  + yearOfRegistration
}

class Owner {
  + taxCode
  + address
  + phoneNumber
}

class Manager {}

class AccountingOffice {}

RepairShop "1" *-- "*" Employee : employs
RepairShop "1" -- "1" Director : directedBy
RepairShop "1" -- "*" Repair : performs
Repair "1" -- "1" Vehicle : involves
Vehicle "1" -- "1" Owner : ownedBy
Manager ..> RepairShop : analyzes
Manager ..> Employee : analyzes
Director ..> RepairShop : manages
Director ..> AccountingOffice : communicates results to

@enduml

